-- ============================================================================
-- 211 — اصلاح نص اللائحة التنفيذية لقانون التمويل العقارى (قرار مجلس الوزراء 1/2001) كاملةً: 79 مادة، من ملف PDF الرسمى (نسخة FRA المحدّثة)
-- ----------------------------------------------------------------------------
-- المشكلة: النص المخزَّن من استخراج PDF فيه (1) حرف "ه" محذوف من مئات الكلمات ("عليه" مخزنة "علي"، "وتكاليفه" "وتكاليف"، "هذا" "ذا"، "رهن" "ر ن")،
--          (2) "لا" مقلوبة ("خالل" بدل "خلال"، "األقساط" بدل "الأقساط")، (3) أقواس البنود مقلوبة ")أ(" وبنود مفصولة عن أرقامها،
--          (4) عناوين الأبواب والفصول مختلطة بمتن بعض المواد (3-إصدار و6 و12 و16 و26 مكرر و37 مكرر و43 و48 و52 مكرر).
-- الإصلاح: أُعيد بناء النص من أحرف الملف نفسه بإحداثياتها (لا من الطبقة النصية التى تقلب "لا")، ثم قورن بالنص المخزَّن مادةً مادة:
--          كل الفروق محصورة فى الأصناف أعلاه (حرف ه/لا المقلوبة/ترتيب الأقواس/العناوين) وأُكّدت الأرقام والكلمات الأخرى مطابقة،
--          ثم رُوجع النص مع قراءة OCR مستقلة لصفحات الملف. الهوامش (*معدلة/مضافة/ملغاة بقرار...) أُبقيت كما هى.
--          تعديلان تحريريان: البند 1 من المادة 4 مكرر كُتب "1-" (الشرطة كانت منفصلة عن الرقم فى الأصل)، وبنود المادة 2 مكرر 1 فُصل فيها "شروط الاستخدام والسداد" فى سطر مستقل.
-- الضمان: كل مادة تُحدَّث فقط إذا كان md5 نصها الحالى أحد النصين المقيسين (قبل/بعد 208) أو كانت "بصمتها الحرفية" (الحروف والأرقام بعد حذف
--          ا أ إ آ ل ه والعلامات) مطابقة لبصمة النص المتوقع؛ غير ذلك: تحذير وتخطٍّ دون كتابة. النص القديم يُحفظ فى migration_211_backup.
--          نسخ article_versions المطابقة تُحدَّث معها. embeddings لا تُمس (يُستحسن إعادة توليدها لهذه المواد). قابلة لإعادة التشغيل.
-- ============================================================================

CREATE TABLE IF NOT EXISTS migration_211_backup (
  article_id uuid NOT NULL,
  version_id uuid,
  old_body   text NOT NULL,
  saved_at   timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_211_backup_art ON migration_211_backup (article_id) WHERE version_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_migration_211_backup_ver ON migration_211_backup (version_id) WHERE version_id IS NOT NULL;

DO $m211$
DECLARE
  r record;
  v_law uuid; v_aid uuid; v_cur text;
  v_ok_art int := 0; v_ok_ver int := 0; v_done int := 0; v_skip int := 0; v_n int;
BEGIN
  SELECT l.id INTO v_law FROM laws l
   WHERE l.country_code = 'EG' AND l.kind = 'regulation' AND l.law_no = 1 AND l.law_year = 2001;
  IF v_law IS NULL THEN
    RAISE WARNING '[211] اللائحة 1/2001 غير موجودة — تخطّى';
    RETURN;
  END IF;
  FOR r IN SELECT * FROM (VALUES
    (1, -1, ARRAY['adca741b5ad10f866a1b47b3aadaa1ac']::text[], '02c790c23c22c594dc2270e7968fcbb9', 'adca741b5ad10f866a1b47b3aadaa1ac', replace($b$يعمل بأحكام اللائحة التنفيذية لقانون التمويل العقاري الصادر بالقانون رقم 148 لسنة 2001 المرافقة لهذا القرار.$b$, E'\n', E'\r\n')),
    (1, 0, ARRAY['9bb12aacc3c9e7b5d5333deef5912c89']::text[], 'bec41699c91772af441172259bb55e83', 'fc165318e43c17b89179ee42d3008bba', replace($b$يكون التمويل العقاري للاستثمار لأغراض السكن والوحدات الإدارية، والمنشآت الخدمية ومباني المحال المخصصة للنشاط التجاري من خلال الأنشطة التالية:
(أ) تمويل شراء المستثمر لعقار أو بناء أو ترميم أو تحسين عقار.
(ب) تمويل شراء العقارات بنظام الإجارة من خلال شراء جهة التمويل للعقار من المستثمر أو من غيره أو ببنائه ثم تأجيرها له بعقد إجارة ينتهي بتملك العقار المؤجر إلى المستثمر في نهاية مدة الإيجار أو أثنائها.
(ج) تمويل شراء حق الانتفاع بالعقارات، وذلك من خلال تمويل شراء المستثمر لهذا الحق من البائع مباشرة أو من خلال قيام جهة التمويل بشراء حق الانتفاع بالعقار بناء على طلب المستثمر، ثم بيع هذا الحق للمستثمر أو بتأجير العين محل حق الانتفاع له إجارة منتهية بتملك هذا الحق.
(د) تمويل بناء أو تحسين أو تطوير عقارات آلت إلى المستثمر بنظام حق الانتفاع، ورهن حق الانتفاع لصالح جهة التمويل طوال فترة سداد قيمة التمويل وتكاليفه.
(ه) التمويل بنظام المرابحة من خلال قيام جهة التمويل بشراء العقار بثمن معلوم لبيعه للمستثمر بالتقسيط بذات الثمن مضافا إليه ربح معلوم وموضح بالعقد.
(و) تمويل شراء العقارات بنظام المشاركة من خلال قيام جهة التمويل بشراء أو بناء العقار مشاركة مع المستثمر، على أن تلتزم جهة التمويل ببيع حصتها إلى المستثمر، أو تأجيرها له إجارة منتهية بالتملك، ويجوز لجهة التمويل بيع حصتها أو تأجيرها إجارة منتهية بالتمليك لغير المستثمر، وذلك بناء على طلب المستثمر.
وتكون مزاولة نشاط إعادة التمويل العقاري عن طريق إعادة تمويل الجهات التي تزاول نشاط التمويل العقاري، وذلك بصيغة من الصيغ التي تزاول بها هذه الجهات ذلك النشاط.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (1, 1, ARRAY['d03642399e684b87c114fbdb72a1c190']::text[], '2e0e74b24184fc5dfcd137942118a384', '6838dc55e97a7f68b70af83c44880e8b', replace($b$تكون إعادة التمويل العقاري بضمان أو بشراء المحافظ العقارية من جهات التمويل، على أن ترهن الاتفاقات الضامنة رهنا حيازيا لصالح شركة إعادة التمويل العقاري ضمانا لمبلغ إعادة التمويل الممنوح لحين الوفاء بقيمته، ولها إصدار سندات بضمان أصولها أو سند التوريق مقابل الحقوق المالية المحالة إليها.
*مضافة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (2, -1, ARRAY['5969789268a36c5902ad182af42e12da']::text[], 'ee2708a7b4d6fbc2c52339f5d09ca8ac', '5969789268a36c5902ad182af42e12da', replace($b$في تطبيق أحكام اللائحة المرافقة يقصد بـ القانون قانون التمويل العقاري وبـ الهيئة الهيئة العامة لشئون التمويل العقاري.$b$, E'\n', E'\r\n')),
    (2, 0, ARRAY['6aa10e5e061671e108f5fe1065407d89']::text[], '927b8bb2d34132d415ffc9c6240ef637', '4fe4aef5edc3b92fb205cf63f524ed2b', replace($b$يكون التمويل العقاري بضمان حق الامتياز على العقار، أو رهنه رهنا رسميا.
كما يجوز في الحالات التالية أن يقبل الممول لإتاحة التمويل العقاري تقديم أحد الضمانات المبينة قرين كل منها:
1- إذا كان العقار محل التمويل غير مسجل باسم البائع في حالة الشراء أو باسم المستثمر في حالة البناء أو الترميم أو التحسين جاز للممول أن يقبل ضمانا للتمويل رهن أصول عقارية مملوكة للمستثمر أو لغيره أو كفالة شخصية من غير المستثمر أو أوراقا مالية مقيدة بالبورصة لا تقل قيمتها عن كامل قيمة الأقساط المستحقة أو قيمة التمويل وتكاليفه، أو قبول المستثمر خصم قيمة أقساط التمويل من راتبه أو دخله، وللممول في هذه الحالات أن يشترط على المستثمر تسجيل العقار محل التمويل باسمه أو قيد حق الامتياز باسمه أو رهنه رهنا رسميا لصالح الممول خلال فترة يتفقان عليها.
2- إذا كان العقار محل التمويل بغرض بناء أو ترميم أو تحسين عقار على أرض مخصصة للمستثمر من الدولة أو من أحد الأشخاص الاعتبارية العامة أو بغرض تمويل شراء وحدة مخصصة للمستثمر من الدولة أو أحد الأشخاص الاعتبارية العامة،
فللممول ضمانا للتمويل وتكاليفه قبول رهن المباني لصالحه أو قبول التنازل له من المستثمر عن التخصيص بصفة مؤقتة طوال فترة التمويل، وذلك بعد موافقة الجهة التي خصصت الأرض أو الوحدة على إجراء هذا التنازل.
3- إذا كان التمويل لشراء المستثمر لحق الانتفاع بالعقار من البائع مباشرة أو كان لبناء أو ترميم أو تحسين عقارات آلت إلى المستثمر بنظام حق الانتفاع فيجوز لجهة التمويل اشتراط رهن هذا الحق لصالحها رهنا رسميا، وفي جميع الأحوال يلتزم الممول بشهر السند المنشئ لهذا الحق.
وفي جميع الأحوال يجوز للممول قبول ما يراه مناسبا من الضمانات الأخرى ضمانا للتمويل في أي من أنشطة التمويل العقاري ووفقا لما يتم الاتفاق عليه في العقد، بمراعاة الضوابط التي تضعها الهيئة في شأن هذه الضمانات.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (2, 1, ARRAY['0b9a004aa1d95b082892cf00a06f71c6']::text[], '47ed227d89e88d99bb9e4819e4d27f54', '5c0dfcd0a1f3337b3785cc29cb79860e', replace($b$يكون التمويل العقاري بموجب اتفاق بين أطراف التمويل على النماذج المعتمدة من الهيئة والتي يجب أن تتضمن البيانات التالية على الأقل:
(أ) وصف العقار وصفا نافيا للجهالة وثمنه أو مقابل حق الانتفاع به.
(ب) مقدار المبلغ المعجل الذي يتم سداده من ثمن العقار أو مقدم للإيجار.
(ج) عدد وقيمة أقساط باقي الثمن أو القيمة الإيجارية أو مقابل حق الانتفاع وشروط الوفاء بها على أن تكون محددة أو قابلة للتحديد سلفا باستخدام معادلة ثابتة مربوطة بأحد المؤشرات الرسمية التي تحددها الهيئة لحساب التغيير في تكلفة التمويل زيادة أو نقصا وذلك لحين استيفائها بالكامل.
(د) القيمة المخفضة التي يتم الوفاء بها في حالات السداد المعجل بحسب التاريخ الذي يتم الوفاء فيه من سنوات أقساط التمويل.
(ه) قبول البائع حوالة حقوقه في أقساط الثمن أو القيمة الإيجارية أو مقابل حق الانتفاع والضمانات المرتبطة بها إلى الممول بالشروط التي يتفقان عليها.
(و) قبول المستثمر بحق الممول في حوالة حقوقة طرف المستثمر إلى الشركة أو إحدى الجهات المرخص لها بمباشرة نشاط التوريق.
(ز) التزام المستثمر في حالة تمويل شرائه أو بنائه أو ترميمه أو تحسينه العقار محل التمويل برهنه أو بقيد حق امتياز الثمن المحالة أقساطه إلى الممول، وذلك ضمانا للوفاء بها.
ويضع مجلس إدارة الهيئة الشروط ويحدد البيانات الواجب تضمينها في اتفاقات التمويل طبقا لطبيعة كل اتفاق، بمراعاة ما يلي:
1- في حالة عقود المشاركة يجب أن يتضمن العقد شروط إدارة المشاركة وتقسيم عوائدها وبيان حصة كل طرف وشروط تملك المستثمر أو غيره لحصة الممول بناء على رغبة المستثمر.
2- في حالة عقود الإجارة يجب أن يتضمن العقد القيمة الإيجارية وتواريخ استحقاقها ونظام البيع وميعاده وثمنه على أن يكون محددا أو قابل للتحديد على أن يراعى في تحديد الثمن مبالغ الأجرة التي أداها المستأجر.
3- في حالة عقود المرابحة يجب أن يتضمن العقد تحديد ثمن شراء العقار والمضاف إليه من ربح معلوم وعدد وقيمة الأقساط ودورية سدادها
4- في حالة عقود تمويل حق الانتفاع يجب أن يتضمن العقد قيمة الانتفاع ومدته وقيمة الأقساط وكيفية التعامل على المباني والإنشاءات التي يقوم الممول بتمويل حق الانتفاع بها، مع الالتزام بقيد حق الانتفاع وقيد الرهن العقاري عليه.
*مضافة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (2, 2, ARRAY['bdbad51fffd4ade0a436601e4bdb43bd']::text[], 'ade4f996c883bbce16dc0f08bd175c61', '13d0a7d72332111e460509f567f0f21b', replace($b$تكون إعادة التمويل العقاري بموجب اتفاق بين طرفي التمويل على النماذج المعتمدة من الهيئة والتي يجب أن تتضمن البيانات التالية على الأقل:
مدة العقد والقيمة الإجمالية لمبلغ إعادة التمويل.
الضمانات المقدمة للحصول على مبلغ إعادة التمويل.
شروط الاستخدام والسداد.
شروط التنازل عن العقد والحوالة.
ويحدد مجلس إدارة الهيئة البيانات الأخرى التي يجب أن يتضمنها اتفاق إعادة التمويل.
*مضافة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (3, -1, ARRAY['ad7b29730327bf0ed54857572e617e49']::text[], '044c7181093a981f624f0a1e453e29a6', '8d5ecb1ad932339e29906e457c2d3905', replace($b$ينشر هذا القرار في الوقائع المصرية، ويعمل به من اليوم التالي لتاريخ نشره.
صدر برئاسة مجلس الوزراء في 24 رمضان سنة 1422 ه
)الموافق 9 ديسمبر سنة 2001م(.$b$, E'\n', E'\r\n')),
    (3, 0, ARRAY['1f33899bd6aa323ee0be481198a52d67']::text[], 'd12496ce2ccef853085be043054bbc94', 'cce41eddbbf3f50174da18788c606d40', replace($b$تكون مزاولة أنشطة ومجالات التمويل العقاري وفقا للقواعد والمعايير التي يحددها مجلس إدارة الهيئة طبقا لطبيعة كل نشاط، كما يضع مجلس إدارة الهيئة القواعد المنظمة لحالات انقضاء عقد الإجارة أو المشاركة أو حق الانتفاع قبل المدة المحددة في العقد بسبب وفاة المستثمر أو عجزه أو امتناعه عن الوفاء بالأقساط المستحقة، وذلك بمراعاة القيمة السوقية للعقار وما قام المستثمر بسداده مقابل تملكه للعقار أو حق الانتفاع به.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (4, 0, ARRAY['62c41ba6e37b96f68f833f6913d7e213']::text[], '93e01f9173b48e5f642fa2a4f8d5a74e', 'f4bedcfe28d23a64cfd3172a264cd4d4', replace($b$على الجهات التي ترغب في إقامة مشروعات بناء مساكن اقتصادية تباع لذوي الدخول المنخفضة المنصوص عليهم في المادة (6)، بنظام التمويل العقاري وبالمزايا التي يقررها القانون في هذا الخصوص، التقدم بطلب إلى صندوق ضمان ودعم نشاط التمويل العقاري مصحوبا بدراسات وافية عن المشروع تتضمن عدد وحداته ومساحاتها والقيمة التقديرية لأثمانها وغير ذلك من العناصر المتصلة بالمشروع.
ويبرم الصندوق اتفاقا مع الجهة الراغبة في إقامة المشروع ومع من يقبل تمويله، يتناول جميع الأحكام المنظمة لإقامة المشروع وأسلوب بيع وحداته السكنية وتمويلها وتحديد نسبة الدعم الذي يقدمه الصندوق.$b$, E'\n', E'\r\n')),
    (4, 1, ARRAY['60701921fea62a861683981d2aa268ea']::text[], '5f8b9ddb5f799676df0fd1c33e731c4e', '579d2ba26ec14c8e6bb8244a5a35bc3e', replace($b$يتم تقدير قيمة العقار عند منح التمويل وفقا للمعايير التي يصدرها مجلس إدارة الهيئة على أن تتضمن على الأخص ما يلي:
1- وصف العقار وموقعه وحدوده ومساحته.
2- تاريخ إنشاء العقار وحالة المرافق الداخلية والعمر الاقتصادي المتبقي.
3- طريقة التقييم المطبقة ومبررات استخدامها وقيمة العقار أو القيمة الإيجارية السوقية وفقا لها وقت التقييم بمراعاة الإحلال والتجديد الذي تم على العقار إن وجد.
4- الحد الأدنى لمشتملات تقرير التقييم.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*مضافة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (5, 0, ARRAY['3a2fdb80f5fbf8e35b8764871a214964']::text[], '21095ab81d60ddac81b22e8dc95e0086', '20445133a73ba2702f8f691a631893d3', replace($b$تلتزم الدولة - ممثلة في الجهات صاحبة الولاية على أراضي الدولة - بتسليم أراض تخصص لإقامة مساكن من المستوى الاقتصادي لذوي الدخول المنخفضة بنظام التمويل العقاري إلى الصندوق، وتتحمل التكلفة الفعلية لتوفير المرافق العامة لها أو جزءا من هذه التكلفة، أو غير ذلك من صور الدعم طبقا لما يتم عرضه بواسطة وزيري المالية والإسكان والمرافق والمجتمعات العمرانية.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (6, 0, ARRAY['db9067caaaf855c52656d38d0c5528f5']::text[], '649ab744726ad11bd00d47f32b6232c7', '433f1a92847324bef4800bb670fe5e5a', replace($b$يقصد بالمستثمر من ذوي الدخول المنخفضة المشار إليهم في المادة (5) من القانون من يتوافر فيه المعايير الآتية:
(أ) ألا يكون مالكا لوحدة سكنية هو أو زوجه أو أولاده القصر.
ب) ألا يكون قد سبق له أو لزوجه الاستفادة بدعم من صندوق ضمان ودعم نشاط التمويل العقاري أو إحدى الجهات العامة التي تقدم دعما للحصول على وحدة سكنية.
(ج) ألا يتجاوز دخله السنوي هو وأسرته الحد الذي يصدر به قرار من مجلس إدارة صندوق ضمان ودعم نشاط التمويل العقاري مراعيا التغيرات في أسعار الوحدات ومستويات الدخل ومعدلات التضخم.
وتكون الأولوية في توفير الدعم للحصول على مسكن اقتصادي للمستثمر الأقل دخلا الذي لم يسبق له الحصول على دعم نقدي ومن لا يملك وحدة سكنية.
*معدلة بقرار رئيس مجلس الوزراء رقم 1 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 1864 لسنة 2008.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (7, 0, ARRAY['62c34bb0970b9ab45ea736c97d30328d']::text[], '54e256e39aa3415a23998efb582f3ef2', 'af5b3b31b60af835c2ba2f2b2da357c7', replace($b$على المستثمر الراغب في التصرف في العقار الضامن أو التنازل عن الإيجار أو حق الانتفاع أو في ترتيب حق عيني عليه أو في تأجيره أو في تمكين الغير من الانفراد بشغله أن يحصل على موافقة الممول الكتابية على ذلك بناء على طلب مكتوب يوجه إليه
قبل الموعد المحدد للتصرف أو الإيجار أو الشغل بمدة لا تقل عن ثلاثين يوما، ويرفق بالطلب المستندات الدالة على شخص المتصرف إليه ودخله أو الضمانات المشار إليها بالمادة (2) من هذه اللائحة.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (8, 0, ARRAY['353d514af2eeaee9927c8c3ad64b072e']::text[], 'd864ffb8e2538515badbc8244d2e64d6', 'fc85b7d0eee5d6649a556afc9934e321', replace($b$يجب أن يُرفق بطلب الموافقة على التصرف أو التأجير أو التنازل عن حق الانتفاع أو ترتيب حق عيني إقرار كتابي من المتصرف إليه بالحلول محل المستثمر في الالتزامات المترتبة على اتفاق التمويل ويجوز للممول أن يشترط على المستثمر تقديم إقرار بتضامنه مع المتصرف إليه في الوفاء بتلك الالتزامات.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (9, 0, ARRAY['f4cc4ca3d4063e76d085904d91304ea0']::text[], '40075d3d6db87afd951334fb140168bb', '55d590ea3b1bc68cdbae0bfccc83fbfb', replace($b$يجوز للممول أن يشترط، للموافقة على تأجير المستثمر للعقار أو شغل الغير له، تقديم إقرار كتابي بحوالة حقه في أجرة العقار أو مقابل شغله إلى الممول وبإعلان المستأجر أو الشاغل بالحوالة، وذلك وفاء لمستحقات الممول لدى المستثمر وفقا لاتفاق التمويل العقاري.$b$, E'\n', E'\r\n')),
    (10, 0, ARRAY['a813bcab5c77e3302a63ab4cd7409f4e']::text[], 'f8cbe8151df248c3c3a39fa582e9f58b', 'c20416343bfd25c5cc2585a11e8dd8cd', replace($b$لا يجوز للممول أن يرفض الطلب المشار إليه في المادة (7) إلا لأسباب جدية تتعرض معها مصالحه وحقوقه للخطر، وعلى أن يقوم الممول بإخطار الطالب بأسباب الرفض بموجب خطاب مسجل بعلم الوصول وذلك خلال ثلاثين يوما من استلام الطلب وإلا اعتبر موافقا عليه.$b$, E'\n', E'\r\n')),
    (11, 0, ARRAY['8972bb397d0769b1d59b3f629c1f6f6b']::text[], 'a480d2684fa80b862998acb870be62dd', '0622081092498255ce4ed3e9f96f15cb', replace($b$إذا رغب المستثمر في التعجيل بالوفاء بكل أو بعض أقساط الثمن أو التمويل أو القيمة الإيجارية أو إبداء الرغبة في التملك أثناء مدة عقد الإجارة، وجب عليه إخطار الممول قبل موعد السداد المعجل بفترة لا تقل عن شهر، ويتم في هذه الحالة خفض الأقساط المستحقة عليه وفقا لجدول السداد المعجل المرفق باتفاق التمويل.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (12, 0, ARRAY['53754a89ee37391c2bd3f6bd308e882b']::text[], '67beb16925513fcec66af5a3cd2e1748', '6c252d05e1ec00bd229fd5165fc7eaea', replace($b$يقدم طلب قيد الضمان العقاري من الممول أو المستثمر تطبيقا لأحكام القانون إلى مكتب الشهر العقاري الكائن في دائرته العقار متضمنا البيانات الآتية:
(أ) أسماء وبيانات كل من الممول والمستثمر.
(ب) قيمة الأقساط والحقوق المضمونة.
(ج) الموعد المحدد لانتهاء الوفاء بأقساط الثمن أو التمويل.
ويجب أن يرفق بالطلب المشار إليه اتفاق التمويل العقاري وسند ملكية العقار باسم المستثمر أو ضمان التمويل باسم الممول.$b$, E'\n', E'\r\n')),
    (13, 0, ARRAY['9fb39597df02beb570bbdfed2b42e10f']::text[], 'b1e8d4e4a610457f8166e67769e97dc3', '8f2fdd16f0e4c19901d9749ba56beb63', replace($b$يتولى مكتب الشهر العقاري المختص التحقق من صحة حدود العقار ومواصفاته الواردة بطلب القيد وسند الملكية المرفق به، وله في سبيل ذلك تكليف الطالب بأن يستوفي ما يلزم من مستندات خلال مهلة لا تقل عن ثلاثة أيام.
ويكون البت في الطلب أو التكليف باستيفاء المستندات خلال أسبوع من تاريخ تقديمه. ولا يجوز
رفض طلب القيد إلا بسبب عدم استيفاء المستندات اللازمة لإجرائه.
وفي جميع الأحوال يجب إخطار الطالب بقبول الطلب أو باستيفاء المستندات أو برفض الطلب مسببا بخطاب مسجل بعلم الوصول وفقا لأحكام القانون.$b$, E'\n', E'\r\n')),
    (14, 0, ARRAY['3e80c8d383ec2a6bb79947dcb9f882c9']::text[], '74ed6bee28a4987d117b208cde59c4bb', '8d84c5ee250ab4733a8e714fcad47f6f', replace($b$مع عدم الإخلال بالأحكام المنظمة لنشاط التوريق الواردة بقانون سوق رأس المال رقم 95 لسنة 1992 ولائحته التنفيذية والقرارات الصادرة تنفيذا لهما، يجب أن يتضمن اتفاق الحوالة الناشئة عن اتفاق التمويل العقاري إلى شركة إعادة التمويل العقاري أو الجهة المرخص لها بمزاولة نشاط التوريق والذي تُعده الهيئة، البيانات التالية على الأقل:
(أ) قبول الممول حوالة حقوقه الناشئة عن اتفاق التمويل العقاري إلى المحال له.
(ب) بيان المقابل الذي التزم به المحال له مقابل الحوالة وشروط الوفاء بهذا المقابل.
(ج) بيان تفصيلي بالحقوق المحالة بما في ذلك الأقساط أو القيمة الإيجارية الخاصة بكل عملية تمويل والعقار الضامن لها وشروط الضمان وبيانات المدين بها وأي ضمانات أخرى (محفظة التوريق/ محفظة إعادة التمويل العقاري).
(د) مدى التزام الممول بتحصيل الأقساط أو القيمة الإيجارية التي تمت حوالتها بصفته نائبا عن المحال له مقابل عمولة تحصيل يحددها الاتفاق
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (15, 0, ARRAY['53e0160dc1a7d889cd4c400af7f2e85a']::text[], '084dacca6083caa8afef27d3bf56d4d6', '804765587234603b29c1a2b2f27b5ef7', replace($b$ملغاة
*ملغاة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.
النص قبل الالغاء: مع عدم الإخلال بضمان الممول للوفاء بالحقوق الناشئة عن الأوراق، يجوز الاتفاق على ضمان الغير للوفاء بالحقوق الناشئة عن الأوراق المالية التي تصدرها الجهة التي تباشر نشاط التوريق على ألا يقل تصنيفه الائتماني عن المستوى الذي تحدده الهيئة العامة لسوق المال وأن يشمل الضمان كافة الأقساط المستحقة وألا يكون معلقا على أي شرط.$b$, E'\n', E'\r\n')),
    (16, 0, ARRAY['f808a7c135d75ea087204374c606fd8e']::text[], '7347642a61da855a4efb1144226acc1a', '27c7a00610b22f17c95cb70ddf90b772', replace($b$على الممول عند حوالة حقوقه الناشئة عن اتفاقيات التمويل العقاري أن يلتزم بالآتي:
(أ) أن يفصح للمحال له عن أسماء المستثمرين المدينين بالحقوق التي تمت حوالتها وبالضمانات المقدمة منهم، وبما قاموا بوفائه من أقساط أو قيم إيجارية أو مقابل حق الانتفاع ومواعيد الوفاء وحالات الامتناع عنه، وذلك كله دون حاجة إلى الحصول على موافقة المستثمرين على هذا الإفصاح.
(ب) إعلان المدين بالرهن بخطاب مسجل مصحوب بعلم الوصول ما لم يتضمن اتفاق التمويل تحديد وسيلة أخرى كما يلتزم بإثبات الرهن لدى الجهة المختصة.
(ج) ألا يتعامل على الحقوق المحالة أو على أي من الضمانات المرتبطة بها مرة أخرى.
(د) إثبات تاريخ العقد بسجل تمسكه الهيئة أو إحدى الجهات التي يحددها مجلس إدارتها.
ويجوز للمتعاقدين تسليم مستندات الحقوق المرهونة إلى جهة أخرى يتفق عليها المتعاقدان من الجهات المعتمدة لدى الهيئة، كما يجوز الاتفاق على أن يحتفظ المحيل بحيازة مستندات الحقوق المرهونة على سبيل الأمانة على أن يلتزم بتسليمها إلى المحال إليه فور طلبها.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (17, 0, ARRAY['4345408ec35fd7114e416464a88f6cd0']::text[], 'abc930ed7ec4ab8da4ea743602305af4', '0bb37c9a63fd6177de8a63b704d597f0', replace($b$لا يجوز للممول البدء في إجراءات التنفيذ على العقار الضامن إلا بعد إنذار المستثمر على يد محضر بالوفاء أو بتقديم ضمان كاف بحسب الأحوال، على أن يتضمن الإنذار ما يأتي:
(أ) تنبيه المدين بالوفاء أو بتقديم ضمان كاف.
(ب) بيان بالأقساط الواجب الوفاء بها أو بالضمان الذي يقبله الممول.
(ج) تحديد المدة التي يجب على المستثمر خلالها الوفاء أو تقديم الضمان على ألا تقل عن ستين يوما من تاريخ الإنذار.
(د) التنبيه على المستثمر بأن انقضاء المهلة المحددة بالإنذار دون الاستجابة له يترتب عليه حلول آجال الأقساط المتبقية وفقا لاتفاق التمويل العقاري.
(ه) تعيين موطن مختار للممول.$b$, E'\n', E'\r\n')),
    (18, 0, ARRAY['72ba377d61c06f750fd00af39d46dbc2']::text[], '0144af30358c37f68ecdfe4fa4289476', '984aec3d492a5bba631f8272ba1f017c', replace($b$يبدأ التنفيذ بإعلان المستثمر والمتصرف إليه وصاحب الحق العيني والمستأجر وحائز العقار باتفاق التمويل بعد وضع الصيغة التنفيذية عليه مع تكليف المستثمر بالوفاء على أن يتضمن الإعلان:
(أ) بيان جهة وتاريخ وضع الصيغة التنفيذية على اتفاق التمويل.
(ب) التكليف بالوفاء بكامل المبالغ المتبقية طبقا لاتفاق التمويل خلال مدة لا تقل عن ثلاثين يوما من تاريخ إعلان التكليف بالوفاء.
(ج) وصف العقار مع بيان موقعه ومساحته وحدوده.$b$, E'\n', E'\r\n')),
    (19, 0, ARRAY['898b434541fe45799e7ebdc33974793b']::text[], 'b4e9bd3d489e8b6d1d158e73f15727f0', 'f6dd643ebda3137c9e520bc719c6db92', replace($b$يقوم الممول بإعلان مكتب الشهر العقاري الواقع بدائرته العقار محل التنفيذ باتفاق التمويل بعد وضع الصيغة التنفيذية عليه وبتكليف المدين بالوفاء وذلك للتأشير به على هامش قيد الضمان العقاري خلال مدة لا تجاوز أسبوعا من تاريخ الإعلان، وعلى الممول إعلان جميع الدائنين المقيدة حقوقهم على العقار وحائزه بالاتفاق بعد وضع الصيغة التنفيذية عليه وبالتكليف بالوفاء وإلا كان التكليف غير نافذ في حقهم.$b$, E'\n', E'\r\n')),
    (20, 0, ARRAY['91df10eef4c388b9de300c99a81a8d53']::text[], '68a8fed36e87d4ddafb366616cc425c1', '3db7b51238f203de705f91abfbb24139', replace($b$يقوم التأشير بالسند التنفيذي في مكتب الشهر العقاري مقام تسجيل تنبيه نزع الملكية، ويترتب عليه اعتبار العقار محجوزا من تاريخ التأشير به.$b$, E'\n', E'\r\n')),
    (21, 0, ARRAY['da93ef2ce122aeab56a3ea2007bc00bd']::text[], '6f80e09e463b26456299846ed8772839', 'ba5edf2459828d24b4185bb2c8dc80f4', replace($b$يعين قاضي التنفيذ في قراره الصادر بمباشرة إجراءات بيع العقار وكيلا عقاريا لمباشرة إجراءات البيع بالمزاد العلني وذلك من بين الوكلاء المقيدة أسماؤهم في سجل تمسكه الهيئة لهذا الغرض وفقا لأحكام الباب السادس من هذه اللائحة على ألا تكون له مصلحة مباشرة أو غير مباشرة من البيع أو مع الممول أو المستثمر.
ويأمر قاضي التنفيذ في قراره الصادر بمباشرة إجراءات البيع طالب التنفيذ بوضع مبلغ يقدره في خزينة المحكمة المختصة لحساب مصروفات التنفيذ.$b$, E'\n', E'\r\n')),
    (22, 0, ARRAY['3c994a51853f90214584f14c6d0ed87d']::text[], '2fabd93c1c71b18686291956a2115af9', '08c0ff5074ef03846601f8270e8a6d5d', replace($b$يعين قاضي التنفيذ اثنين من خبراء التقييم المشار إليهم في المادة (4) من القانون - منفردين - لتحديد الثمن الأساسي للعقار بمراعاة معايير التقييم الصادرة عن مجلس إدارة الهيئة.
ويحدد الوكيل العقاري تأمين الاشتراك في المزاد على ألا يقل عن واحد في المائة ولا يجاوز خمسة في المائة من الثمن الأساسي للعقار وبحد أدنى عشرة آلاف جنيه.
وفي جميع الأحوال يستحق خبير التقييم تقاضي أتعابه بغض النظر عن التنفيذ على العقار من عدمه.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (23, 0, ARRAY['e076b530972b4c9f1d1538a77e54b409']::text[], '0090f26d0981d5cdbfc36f0a5e2a5491', 'eda2b6190ef8f4fd77d2631fd5bc9621', replace($b$يقوم الوكيل العقاري بوضع قائمة شروط بيع العقار بالمزاد العلني خلال خمسة عشر يوما من تاريخ التأشير بالسند التنفيذي على أن تتضمن ما يأتي:
(أ) تعيين العقار محل التنفيذ ومساحته وموقعه وحدوده وغير ذلك من البيانات التي تفيد في بيان أوصافه.
(ب) جهة وتاريخ وضع الصيغة التنفيذية على اتفاق التمويل العقاري.
(ج) تاريخ وجهة التأشير بالسند التنفيذي لدى مكتب الشهر العقاري.
(د) تاريخ وساعة ومكان إجراء البيع.
(ه) شروط البيع والثمن الأساسي للعقار.
(و) تجزئة العقار إلى صفقات إن كان لذلك محل مع ذكر الثمن الأساسي لكل صفقة.
(ز) مقدار تأمين الاشتراك في المزاد على ألا يقل عن واحد في المائة ولا يجاوز خمسة في المائة من الثمن الأساسي للعقار.$b$, E'\n', E'\r\n')),
    (24, 0, ARRAY['29ac189dbd41d43a59a9970af0c8135e']::text[], '3d800225a14a34cdbeef8a9c0d863c1c', 'b253ddf74367569582d885b0b48e7bf0', replace($b$على الوكيل العقاري قبل البدء في إجراءات المزايدة التحقق من إعلان ذوي الشأن في المواعيد المنصوص عليها في المادة (19) من القانون بقائمة شروط البيع وتحديد مقادير التدرج في العروض وإعلان الحاضرين بها.$b$, E'\n', E'\r\n')),
    (25, 0, ARRAY['55f7dc4cd8f1ddc9ec33c0b1b5a790a3']::text[], '1daf9e8716144417113981debfadd97d', '84e21d2cd5be635ae8e13af45f0519ea', replace($b$يقوم الوكيل بإيداع حصيلة البيع خزينة المحكمة خلال ثلاثة أيام من تاريخ حكم إيقاع البيع.$b$, E'\n', E'\r\n')),
    (26, 0, ARRAY['3c6d832e2da1f69328e510a034bf39c9']::text[], 'aa82d1acdc4cd8da6923c1f7740c2006', 'e8360d5ce24a3f17ec09e10ddc98dfa3', replace($b$تُقدر أتعاب الوكيل العقاري بقرار من قاضي التنفيذ وفقا لما بذله الوكيل من جهد لإنجاز إجراءات البيع والوقت الذي استغرقته تلك الإجراءات على ألا تجاوز ثلاثة في المائة من القيمة التي رسا بها المزاد وبحد أدنى ثلاثة آلاف جنيه.
كما يحدد قاضي التنفيذ مقابل أتعاب الوكيل في حالة قيام المدين بالسداد أثناء مباشرة الإجراءات وقبل إيقاف البيع وبحد أدنى ألف وخمسمائة جنيه.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (26, 1, ARRAY['944e1102727c08b34d7920894d45ec5d']::text[], '8b102810769e559b4fad20b668f562ae', 'e65525ef130a6e727007db6b1f8b2d1d', replace($b$في الحالات التي يقبل فيها الممول ضمانات للتمويل بخلاف قيد حق الامتياز على العقار أو رهن العقار الضامن رهنا رسميا، يكون للممول في حالة إخلال المستثمر بالتزاماته طبقا لاتفاق التمويل أو عدم التزامه بسداد الأقساط المتفق عليها في مواعيدها طبقا لاتفاق التمويل وبعد إنذاره طبقا للمواعيد والإجراءات المحددة بالمادة (12) من القانون، أن يطلب من القاضي المختص الأمر بالتنفيذ على الضمانات المقدمة طبقا لما يتضمنه اتفاق التمويل.
ويراعى عند التنفيذ على الضمانات المقدمة لاستئداء المبالغ المتبقية من قيمة التمويل مراعاة القيمة المخفضة للسداد المعجل المرفق باتفاق التمويل. وفى حالة عدم قيد الضمان العقارى الوارد باتفاق التمويل لصالح الممول، وحالات التنازل المؤقت عن التخصيص لصالح الممول وفقا للمادة (2) من هذه اللائحة، وكذا حالات الإجارة والمشاركة والمرابحة، يجوز للممول حال عدم وفاء المستثمر بالمبالغ المستحقة عليه ومضى ثلاثين يوما من تاريخ استحقاقها أن يقوم بإنذار المستثمر بالوفاء خلال ستين يوما على أن يتضمن الإنذار البيانات المنصوص عليها بالمادة (17) من هذه اللائحة.
ويكون للممول فى حالة عدم سداد المستثمر للمبالغ المستحقة خلال المدة المشار إليها بالفقرة السابقة أن يطلب من قاضى التنفيذ الذي يقع العقار الضامن في دائرة اختصاصه الأمر بالتنفيذ على ذلك العقار وتعيين وكيل عقارى من بين الوكلاء المقيدين لدى الهيئة، وذلك لمباشرة إجراءات بيع العقار تحت الإشراف المباشر لقاضى التنفيذ وتتبع الإجراءات التالية لاستيداء مستحقاته:
(أ) تحديد القيمة السوقية للعقار بواسطة خبيرين من خبراء التقييم العقارى المقيدين لدى الهيئة.
(ب) بيع العقار وفقا لأعلي سعر متاح يراعى التقييمات المعدة من خبيرى التقييم العقارى وحصول الممول على مستحقاته بالإضافة إلى غرامات التأخير وكافة المصروفات والتكاليف التى تكبدها حتى تاريخ البيع، ورد المبلغ المتبقى من حصيلة البيع بالكامل للمستثمر.
*معدلة بقرار رئيس مجلس الوزراء رقم 32 لسنة 2024.
*مضافة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (27, 0, ARRAY['38f1cbf90de613d5c02e7a2c324a81cf']::text[], 'b6a5ab001a5bd72cce223adbe9ff3fce', '26787bbccf1a6b605f187e360f3eb3fd', replace($b$يجب أن تتخذ الشركة التى يرخص لها بمزاولة نشاط التمويل العقارى شكل شركة مساهمة مصرية، وألا يقل رأس مالها المصدر والمدفوع عن مائة مليون جنيه نقدا أو ما يعادلها بالعملات الأجنبية بسعر الصرف المعلن من البنك المركزى المصرى فى تاريخ تأسيس الشركة.
كما يجب ألا يقل رأس مال شركات إعادة التمويل عن مائتين وخمسين مليون جنيه ولا يقل المدفوع منه عند التأسيس عن النصف نقدا، وأن تلتزم الشركة خلال ثلاث سنوات على الأكثر من تاريخ قيدها بالسجل التجاري باستكمال رأس مالها المدفوع ليصبح مائتين وخمسين مليون جنيه على الأقل.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.
*معدلة بقرار رئيس مجلس الوزراء رقم 32 لسنة 2024.$b$, E'\n', E'\r\n')),
    (28, 0, ARRAY['b757eac2dce49aab1f7d201514fdb1dc']::text[], '053ae180bb4c3a6c36c8dd119a6bc01b', '4add6e821e3732dae7a8d50e81ad4047', replace($b$يقدم طلب الترخيص على النموذج الذي تعده الهيئة لذلك، على أن يرفق به ما يأتي:
(أ) العقد الابتدائي للشركة ونظامها الأساسي على أن يكون غرض الشركة مزاولة نشاط أو أكثر من أنشطة التمويل العقاري الواردة بالمادة (1) من القانون، ويجوز للهيئة ووفقا للضوابط التي تضعها الترخيص للشركة بمزاولة أنشطة مالية غير مصرفية أخرى مرتبطة بنشاطها، وذلك فيما عدا شركات إعادة التمويل العقاري فيجب أن يقتصر غرضها على مزاولة نشاط إعادة التمويل العقاري.
(ب) السجل التجاري للشركة.
(ج) المؤهلات العلمية والخبرات العملية لرئيس وأعضاء مجلس الإدارة والمديرين.
(د) شهادة بعدم صدور حكم بالإفلاس أو الإعسار ضد كل من مؤسسي الشركة ورئيس وأعضاء مجلس الإدارة والمديرين ما لم يكن قد رُد إليه اعتباره.
(ه) إقرارات من مؤسسي الشركة ورئيس وأعضاء مجلس الإدارة والمديرين بأنه لم يصدر ضد أي منهم حكم بعقوبة جناية أو بعقوبة جنحة في جريمة ماسة بالشرف أو الأمانة ما لم يكن قد رُد إليه
(و) شهادة من مراقبين للحسابات من المقيدة أسماؤهم لدى الهيئة بقبول مراجعة حسابات الشركة.
(ز) بيان بالمساهمات التي تمثل نسبة (10%) على الأقل في أية مؤسسات مالية أخرى عاملة في مصر والمملوكة للمؤسسين أو المساهمين الذين تزيد نسبة ملكيتهم عن (10%) من أسهم الشركة.
(ح) الإيصال الدال على سداد قيمة رسم الترخيص.
ويصدر مجلس إدارة الهيئة قرارا بالمتطلبات والمستندات الأخرى التي يجب تقديمها للحصول على ترخيص مزاولة النشاط.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (29, 0, ARRAY['a063d5c283dd921406f5d5ea15e934c5']::text[], '26fee41a5c7b661b7c0d29120b788aed', '5e2e6b958d45b544cfac88b09b0ec382', replace($b$يكون رسم الترخيص للشركة عشرة آلاف جنيه.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (30, 0, ARRAY['12647424707dcc1e670557b6a88d39be']::text[], 'f2442a6adfd7230475b7b3734e4798fd', '9c4bd9fa65904ce828a3437360676645', replace($b$يشترط لمنح الترخيص ما يأتي:
(أ) استيفاء المتطلبات المشار إليها في المادتين (27)، (28) من هذه اللائحة.
(ب) ألا تقل نسبة مساهمة الأشخاص الاعتبارية والمؤسسات المالية في شركات إعادة التمويل عن (75%)، وألا تقل نسبة مساهمة المؤسسات المالية عن (50%)، ويقصد بالمؤسسات المالية الشركات والجهات الخاضعة لرقابة البنك المركزي المصري
أو الهيئة أو تلك الخاضعة لرقابة هيئات أو جهات خارجية تمارس اختصاصا مثيلا لاختصاص البنك المركزي المصري أو الهيئة.
(ج) أن يتوفر في رئيس وغالبية أعضاء مجلس الإدارة خبرة عملية في أحد مجالات العمل التمويلي أو المصرفي أو المالي أو القانوني أو التأميني، على أن يتوفر في العضو المنتدب أو المدير التنفيذي للشركة خبرة في أحد مجالات العمل المصرفي أو التمويلي لا تقل عن عشر سنوات بعد الحصول على مؤهل عال.
(د) أن يتوفر في مديري الإدارات المالية والقانونية والائتمان وإدارة المخاطر والمراجعة الداخلية وفي مديري الفروع خبرة عملية في أحد مجالات العمل المصرفي أو التمويلي أو القانوني لا تقل عن سبع سنوات بعد الحصول على مؤهل عال في أحد المجالات ذات العلاقة.
(ه) أن يتضمن تشكيل مجلس الإدارة عضوين على الأقل من المستقلين وفقا للمعايير التي يحددها مجلس إدارة الهيئة.
ويحدد مجلس إدارة الهيئة الشروط الأخرى لمنح الترخيص.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (31, 0, ARRAY['78aadb78d957e0c2f5e6010a8dd391d2']::text[], 'af112edb2b8fb1bab5d9734479c0cb4e', 'd1df0709a0a2a4f0567c23e485b943eb', replace($b$تقوم الهيئة بإعطاء طالب الترخيص شهادة باستلام الطلب والمستندات المرفقة به، وتكليف الطالب، بموجب بيان يسلم إليه خلال عشرة أيام من تاريخ تقديم الطلب، باستيفاء ما قد يلزم من مستندات خلال الثلاثة أشهر التالية لهذا التكليف وإلا سقط طلبه.
وعلى الهيئة البت في طلب الترخيص وإخطار الطالب بقرارها في شأنه بموجب كتاب مسجل بعلم الوصول، وذلك خلال ثلاثين يوما من تاريخ استيفاء المستندات.$b$, E'\n', E'\r\n')),
    (32, 0, ARRAY['3fa5921582e17e3d5a8f6334427228ea']::text[], '4750a08eaa5ee4462e9e5bb418a2ab74', '0ce770bc06fe3ef69364eb636438f865', replace($b$يصدر بالترخيص قرار من رئيس الهيئة ولا يجوز رفض الترخيص إلا بقرار مسبب وفي الحالات المبينة في المادة (31) من القانون.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (33, 0, ARRAY['f834fc52bcc7eda2df4f7719114f5bba']::text[], '37ea6f84b50a75332cf3bc2641160688', '327d52564214c772c397d39b196667d1', replace($b$تقيد الشركات التي يرخص لها بمزاولة نشاط أو أكثر من أنشطة التمويل العقاري في سجل قيد الأشخاص الاعتبارية العامة والشركات الذي تعده الهيئة لهذا الغرض، ويتضمن القيد البيانات التي يحددها مجلس إدارة الهيئة.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
