*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (46, 0, ARRAY['79d1a9c052400464d9732360db505a61']::text[], '7a20ccdd88f96a21f466f163ee90ac4d', 'd50b7abc5ee5a286e3e1191b364609c5', replace($b$يحظر على خبراء التقييم أداء أعمال تقييم بغرض التمويل إذا كانت العقارات مملوكة لهم أو لأي من أقاربهم حتى الدرجة الرابعة أو لأحد من تابعيهم أو شركائهم أو من ينوبون عنهم أو كانت تربطهم علاقة بأحد أطراف التمويل العقاري، كما يحظر عليهم شراء عقار قاموا بتقييمه خلال السنوات الثلاث التالية للتقييم.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (47, 0, ARRAY['6e1f3287c1086a503338d2a5b59a3a41']::text[], '73ba82a1899b22e07f1c68be76ed2dce', '2349654e6adb944bcfce79a4e108ea42', replace($b$إذا لم يقبل واحد أو أكثر من أطراف اتفاق التمويل العقاري التقييم الذي أجرى تطبيقا للمادة (4) من القانون، تولت الهيئة بناء على طلب من الطرف المعترض تكليف خبيرين آخرين بإعادة تقييم العقار، على أن يتحمل طالب إعادة التقييم أتعابه.$b$, E'\n', E'\r\n')),
    (48, 0, ARRAY['546d285c40585e1559810fc71bd4b006']::text[], '1c0d644b325d11ce47ec3a079a9bac0f', '74a2dd0d0912b54ad652951d9c0813f9', replace($b$يضع مجلس إدارة الهيئة قواعد وإجراءات تقدير أتعاب التقييم للوحدات التي يدعمها صندوق ضمان ودعم نشاط التمويل العقاري.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (49, 0, ARRAY['c5cbcbd18a94d0ee8d8da5838fdd318b']::text[], '58c1f16e98f22c63106494221d42440b', '5c7c7c8847c7fa18de962f0b7b0ec97e', replace($b$يلتزم الوسيط بتسليم طالب التمويل صورة من النموذج الذي تعده الهيئة بالشروط الأساسية للتمويل العقاري، وبأن يعرض شروط التمويل ومخاطره على طالب التمويل ويجب أن يرفق مع اتفاق التمويل إقرارات المستثمر بأن تسلم تلك الصورة واطلع عليها قبل التوقيع على اتفاق التمويل.$b$, E'\n', E'\r\n')),
