*ألغيت بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (52, 1, ARRAY['57d998c35899b5ca91520e31887f873a']::text[], '4fca01811b8f3c362fa7d4bb45e94856', '06158f03bdaccb238c9d3fd17b22ebcc', replace($b$يضع مجلس إدارة الهيئة القواعد والمعايير المنظمة لمزاولة أعمال خبراء التقييم العقاري والوكلاء العقاريين والوسطاء العقاريين.
*مضافة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (53, 0, ARRAY['826cf85ad917640c5d44a39db3b41cfa']::text[], '3f897c2f734f20e7720064fd3a9f1f8c', '778842f24f89a1bb905d20053d0c0f24', replace($b$لمن يرغب من ذوي الدخول المنخفضة الحصول على دعم لشراء مسكن اقتصادي أو الانتفاع به أو استئجاره إيجارا ينتهي بالتملك، أو استئجاره، أو يتقدم بطلب بذلك إلى أحد فروع صندوق ضمان ودعم نشاط التمويل العقاري أو أحد من يفوضه الصندوق في ذلك نيابة عنه على النموذج الذي يعده لهذا الغرض مرفقا به ما يأتي:
(أ) وصف العقار وموقعه إذا لم يكن ضمن المشروعات المتاحة بالصندوق ومستندات ملكيته.
(ب) شهادة من أحد خبراء تقييم العقارات بإقرار الثمن المعروض.
(ج) شهادة بإثبات صافي الدخل السنوي للطالب.
(د) أي مستندات أخرى يطلبها الصندوق.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (54, 0, ARRAY['fe33b1bbc91ffb38f630ddbe1ecc798d']::text[], 'e5b33010f5304b710fc03c947ad8b98b', 'e18e6edc9da93e3758a4b435df3ea3ae', replace($b$يقوم الصندوق بدراسة طلب الحصول على الدعم والتأكد من صحة بيانات المستثمر والمستندات المقدمة منه مع إخطار الطالب بالقرار الصادر بشأنه خلال واحد وعشرين يوما من تاريخ تقديمه، ويجب أن يتضمن القرار في حالة الموافقة تحديد شروط التمويل والدعم الذي يقدمه الصندوق وموعد وإجراءات التعاقد بما يكفل توفير الدعم خلال مدة لا تتجاوز ثلاثين يوما من تاريخ قبول الطلب.
وفي حالة رفض الصندوق لطلب الحصول على الدعم يتم إخطار الطالب بأسباب الرفض مع حفظ حقه في التظلم من هذا القرار خلال عشرة أيام من تاريخ الإخطار أمام لجنة يشكلها الصندوق لهذا الغرض.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (54, 1, ARRAY['e93a6c49e233d9dc3326f4bc4ecd1750']::text[], '22d0a0827a822b8cce20dbe3020936fe', '086b8c8ffcc2902744313b25635300c3', replace($b$يحظر على المستثمر أو المستفيد استعمال الوحدة السكنية المدعومة من صندوق ضمان ودعم نشاط التمويل العقاري لغير سكناه هو وأسرته، كما يحظر عليه التصرف في هذه الوحدة أو التعامل عليها قبل مضي سبع سنوات من تاريخ الحصول على الدعم أو الحصول على موافقة الصندوق، ويقع باطلا كل تصرف من التصرفات أو المعاملات التي تتم بالمخالفة لذلك كما يحظر على مصلحة الشهر العقاري والتوثيق - بغير موافقة الصندوق - شهر أو تسجيل أو التسجيل العيني أو التصديق أو إثبات التاريخ على التصرفات أو إجراء التوكيلات أو التنازلات أو إجراء أي تعاملات على تلك الوحدات، وذلك فيما عدا تسجيل الوحدة باسم المستثمر والتوكيلات التي تتم لتسجيل الوحدة وقيد الرهن أو حق الامتياز لصالح جهات التمويل العقاري من بنوك وشركات التمويل العقاري. ويلتزم صندوق ضمان ودعم نشاط التمويل العقاري بإبلاغ وزارة العدل بأسماء المستثمرين وبالوحدات السكنية السابق دعمها من الصندوق لحظر التصرف فيها أو التعامل عليها وبداية ونهاية فترة الحظر، وعلى وزارة العدل إخطار المحاكم ومصلحة الشهر العقاري لإصدار تعميم بالأسماء وبالوحدات المدعومة والمبلغة إليها لمنع أي تصرف أو تعامل على هذه الوحدات السكنية دون غيرها من الوحدات غير المخطر عنها بدون الحصول على موافقة كتابية مسبقة من الصندوق على أن يستثنى من ذلك الحظر التوكيلات والدعاوى لصالح جهات التمويل لتسجيل تلك الوحدات بأسماء المستثمرين لقيد الضمان عليها في حالات الوحدات المباعة بنظام التمليك أو حق الانتفاع أو أسماء جهات التمويل في حالات الإيجار الذي ينتهي بالتملك والمشاركة.
*مضافة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (55, 0, ARRAY['db13f592723dc4054ae414275450feea']::text[], '7bdf0617cb673efda69c8d00cb96f270', '769d9ecc1da0cd10cf33b8915709352b', replace($b$يجوز للصندوق مباشرة الأنشطة واتخاذ الإجراءات والقرارات اللازمة لضمان تحقيق أغراضه وضمان مخاطر عدم سداد الالتزامات الناشئة عن نشاط التمويل العقاري، وله في سبيل ذلك تأسيس أو المساهمة في تأسيس شركات وصناديق متخصصة في ذلك أو الاستعانة بالشركات أو الصناديق القائمة أو بتقديم ضمانات تيسر عمليات التمويل العقاري للممولين أو المستثمرين أو بغير ذلك من الوسائل التي يوافق عليها مجلس إدارته.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (56, 0, ARRAY['a7f73a8afe6ddd91a2864833eb923e50']::text[], '92c9ebc06b7c612b03db162985ac2fbd', '61e028633c9997c2ef706bc6ef63126f', replace($b$إذا اشترط الممول على المستثمر أن يؤمن لصالحه بقيمة حقوقه وفقا لاتفاق التمويل العقاري ضد مخاطر عدم الوفاء بسبب الوفاة أو العجز، تعين أن يكون ذلك لدى شركة تأمين مصرية ووفقا للشروط الآتية:
(أ) قيام شركة التأمين بسداد مبلغ التأمين للمؤمن لصالحه بناء على شهادة وفاة المستثمر أو شهادة طبية بعجزه الكلي أو الجزئي بنسبة تؤثر على قدرته على العمل والكسب صادرة من إحدى الجهات الطبية التي تحددها شركة التأمين من القائمة المعتمدة من الهيئة.
(ب) للشركة إضافة قيمة قسط التأمين الذي يتحمله المستثمر إلى تكلفة التمويل الذي يلتزم المستثمر بسداده إلى الممول ليقوم بسداده إلى شركة التأمين.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (57, 0, ARRAY['9edb655a9d0b2c04bd9bfc6c2d6098ef']::text[], 'd79cdb3d0aecb988c5e1b85302046cb9', '5c14a1248d4697b8af8a5ce7189387dd', replace($b$يلتزم الممول بإبلاغ المستثمر مرتين سنويا على الأقل بجميع البيانات المتعلقة باتفاق التمويل وكذلك عند حدوث أي تعديل في هذه البيانات، وذلك كله وفقا لما يصدر به قرار من مجلس إدارة الهيئة بشأن الحد الأدنى للبيانات التي يتم إخطار المستثمر بها.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (58, 0, ARRAY['254c1a31eee6d2d36c042171bbf65af8']::text[], '9bd6ae5343e1b9aa1e0e05f643ded081', '3b45042d6eb6bc57c97d2c05639d5d73', replace($b$يُنشأ لدى الهيئة مكتب يختص بتلقي وفحص الشكاوى التي يقدمها أصحاب الشأن من المتعاملين بالتمويل العقاري عن مخالفة أحكام القانون أو القرارات الصادرة تنفيذا له.
وتقدم الشكوى إلى المكتب من صاحب الشأن أو نائبه كتابة وتقيد في سجل يعد لهذا الغرض ويُسلم لمقدم الشكوى إيصال بتاريخ تقديمها ورقم قيدها بالسجل.
ويجب على المكتب إخطار مقدم الشكوى بنتيجة فحصها وما اتخذ من إجراءات بشأنها خلال مدة لا تجاوز شهرا من تاريخ استيفاء المستندات والبيانات التي تطلبها الهيئة.
وعلى المكتب إعداد تقرير نصف سنوي يعرض على مجلس إدارة الهيئة يتضمن أعدادا وموضوعات الشكاوى، وما تم فيها من إجراءات، وما يراه من ملاحظات واقتراحات.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n')),
    (59, 0, ARRAY['d79d6dc195b6f912f3734d08f4f7719a']::text[], '66c201298f82ee22c573f9962162ab5b', 'd79d6dc195b6f912f3734d08f4f7719a', replace($b$ملغاة
*ألغيت بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (60, 0, ARRAY['d79d6dc195b6f912f3734d08f4f7719a']::text[], '66c201298f82ee22c573f9962162ab5b', 'd79d6dc195b6f912f3734d08f4f7719a', replace($b$ملغاة
*ألغيت بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.$b$, E'\n', E'\r\n')),
    (61, 0, ARRAY['97bec64db4b295a6f4b05d38eb79bf3a']::text[], '618fcaa70696dbadea400a20cc3a5953', '34b2bcba026153173eff7a84496bae68', replace($b$مع عدم الإخلال بأحكام القوانين المنظمة لسرية المعلومات، يجوز لكل ذي شأن الاطلاع لدى الهيئة على السجلات والتقارير والمستندات وغيرها من الأوراق المتعلقة بنشاط التمويل العقاري والحصول على مستخرجات رسمية منها وذلك وفقا لأحكام المادة (43) من القانون، ومقابل أداء رسم مقداره خمسون جنيها للاطلاع وعشرون جنيها عن كل ورقة من أوراق المستخرجات الرسمية بحد أقصى مائة جنيه عن كل مستخرج.
وللجهة الإدارية أن ترفض الطلب إذا كان من شأن إجابته الإضرار بنشاط التمويل العقاري أو المساس بالصالح العام.
*معدلة بقرار رئيس مجلس الوزراء رقم 2 لسنة 2015.
*معدلة بقرار رئيس مجلس الوزراء رقم 465 لسنة 2005.$b$, E'\n', E'\r\n'))
  ) AS t(art_no, suffix, old_md5s, old_skel, new_md5, new_body) ORDER BY art_no, suffix
  LOOP
    IF md5(r.new_body) <> r.new_md5 THEN
      RAISE EXCEPTION '[211] نص المادة %/% المحمَّل لا يطابق md5 المختبَر', r.art_no, r.suffix;
    END IF;
    v_aid := NULL; v_cur := NULL;
    SELECT a.id, a.body INTO v_aid, v_cur FROM articles a
     WHERE a.law_id = v_law AND a.article_no = r.art_no AND a.article_suffix_order = r.suffix;
    IF v_aid IS NULL THEN
      RAISE WARNING '[211] المادة %/% غير موجودة — تخطّى', r.art_no, r.suffix;
      v_skip := v_skip + 1; CONTINUE;
    END IF;
    IF md5(v_cur) = r.new_md5 THEN
      v_done := v_done + 1; CONTINUE;
    END IF;
    IF NOT (md5(v_cur) = ANY (r.old_md5s)
            OR md5(regexp_replace(v_cur, '[^ء-ي0-9]|[اأإآلهـ]', '', 'g')) = r.old_skel) THEN
      RAISE WARNING '[211] نص المادة %/% الحالى يختلف عن المتوقع (md5 %) — تُخطّيت دون تعديل، راجعها يدوياً', r.art_no, r.suffix, md5(v_cur);
      v_skip := v_skip + 1; CONTINUE;
    END IF;

    INSERT INTO migration_211_backup (article_id, version_id, old_body)
      SELECT a.id, NULL, a.body FROM articles a WHERE a.id = v_aid ON CONFLICT DO NOTHING;
    INSERT INTO migration_211_backup (article_id, version_id, old_body)
      SELECT v.article_id, v.id, v.body FROM article_versions v
       WHERE v.article_id = v_aid AND v.body = v_cur ON CONFLICT DO NOTHING;

    UPDATE article_versions SET body = r.new_body WHERE article_id = v_aid AND body = v_cur;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_ok_ver := v_ok_ver + v_n;
    UPDATE articles SET body = r.new_body WHERE id = v_aid AND body = v_cur;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n <> 1 THEN
      RAISE EXCEPTION '[211] عدد المواد المعدلة % بدل 1 (المادة %/%)', v_n, r.art_no, r.suffix;
    END IF;
    IF (SELECT md5(body) FROM articles WHERE id = v_aid) <> r.new_md5 THEN
      RAISE EXCEPTION '[211] نص المادة %/% بعد التعديل لا يطابق المختبَر', r.art_no, r.suffix;
    END IF;
    v_ok_art := v_ok_art + 1;
  END LOOP;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law) <> 79 THEN
    RAISE EXCEPTION '[211] عدد مواد اللائحة تغيّر عن 79';
  END IF;
  RAISE NOTICE '[211] اللائحة 1/2001: مواد معدَّلة % ، نسخ معدَّلة % ، مُصلَحة سابقاً % ، متخطّاة %', v_ok_art, v_ok_ver, v_done, v_skip;
END
$m211$;
